package com.aetherforge.repo;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class FactoryRepository {private final JdbcTemplate db;public FactoryRepository(JdbcTemplate db){this.db=db;}public List<Map<String,Object>> factories(){return db.queryForList("select id,code,name,timezone,status from factory order by name");}public Map<String,Object> summary(String id){return db.queryForMap("select f.id,f.name,f.code,(select count(*) from machine m where m.factory_id=f.id) machines,(select count(*) from machine m where m.factory_id=f.id and m.status='RUNNING') running,(select coalesce(round(avg(m.health),1),0) from machine m where m.factory_id=f.id) health,(select coalesce(round(avg(p.oee)*100,1),0) from production_metric p where p.factory_id=f.id and p.recorded_at>now()-interval '24 hours') oee,(select coalesce(sum(e.kwh),0) from energy_metric e where e.factory_id=f.id and e.recorded_at>now()-interval '24 hours') energy,(select count(*) from alert a where a.factory_id=f.id and a.status='OPEN') alerts from factory f where f.id::text=?",id);}}
